{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. -#}
{%- set v_login = (p.login ?? null) -%}
{%- set v_loginHref = (p.loginHref ?? null) -%}
{%- set v_cta = (p.cta ?? null) -%}
{%- set v_ctaHref = (p.ctaHref ?? null) -%}
{%- set v_actions = (p.actions ?? 'cta') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_themeLabel = (p.themeLabel ?? null) -%}
{%- if og_t(v_login) %}
  {%- set c_1 -%}
    {{ og_text(v_login) }}
  {%- endset -%}
  {{ include('compose/Button.html.twig', {'variant': 'ghost', 'size': 'sm', 'href': og_url(og_s(v_loginHref)), 'class': og_s((og_t(og_eq(v_tone, 'inverse')) ? 'text-background hover:bg-background/10' : '')), 'children': c_1}, with_context = false) }}
{%- endif %}
{%- if og_t(og_and([og_eq(v_actions, 'cta'), v_cta])) %}
  {%- set c_2 -%}
    {{ og_text(v_cta) }}
  {%- endset -%}
  {{ include('compose/Button.html.twig', {'variant': og_s((og_t(og_eq(v_tone, 'inverse')) ? 'secondary' : 'default')), 'size': 'sm', 'href': og_url(og_s(v_ctaHref)), 'children': c_2}, with_context = false) }}
{%- endif %}
{%- if og_t(v_themeLabel) %}
  {%- set c_3 -%}
    {{ og_text(v_themeLabel) }}
  {%- endset -%}
  {{ include('compose/Button.html.twig', {'variant': 'outline', 'size': 'sm', 'children': c_3}, with_context = false) }}
{%- endif %}
